1	#!/usr/bin/env bun
2	/**
3	 * restore_workspace.ts — put back the working files this issue's agents left last
4	 * run.
5	 *
6	 * Runs before the agent. A first run for an issue restores nothing, which is the
7	 * ordinary case and not a failure: the directory is created either way, so the
8	 * agent finds an empty one rather than a missing one. Those are different things to
9	 * a model reading a tool result, and only one of them invites a retry.
10	 *
11	 * Usage:
12	 *   restore_workspace.ts --type issue|pr --number N --dest /tmp/atomaton-workspace
13	 *     [--repo owner/name]
14	 *
15	 * Writes `root_issue` and `restored` to $GITHUB_OUTPUT so the save step at the end
16	 * of the run writes back to the same place without resolving the chain twice --
17	 * a second resolution could disagree with the first if a parent tag changed
18	 * mid-run, and then the run would read from one workspace and write to another.
19	 */
20	import { appendFileSync, mkdirSync } from "node:fs";
21	import { parseArgs } from "node:util";
22	import { restoreWorkspace, workspaceTargetPrefix } from "./lib/atomaton-data.ts";
23	import { resolveWorkspaceScope } from "../lib/workspace-scope.ts";
24	import { defineScript } from "./lib/script-ref.ts";
25	
26	export interface RestoreWorkspaceArgs {
27	  type: string;
28	  number: string | number;
29	  dest: string;
30	  repo?: string;
31	}
32	
33	export const ref = defineScript<RestoreWorkspaceArgs>(import.meta.url);
34	
35	function main(): void {
36	  const { values } = parseArgs({
37	    args: Bun.argv.slice(2),
38	    options: {
39	      type: { type: "string" },
40	      number: { type: "string" },
41	      dest: { type: "string" },
42	      repo: { type: "string" },
43	    },
44	  });
45	
46	  const repo = values.repo ?? process.env.GITHUB_REPOSITORY ?? "";
47	  if (!values.type || !values.number || !values.dest || !repo) {
48	    console.error("usage: restore_workspace.ts --type issue|pr --number N --dest PATH [--repo owner/name]");
49	    process.exit(2);
50	  }
51	
52	  const scope = resolveWorkspaceScope(repo, values.type, values.number);
53	  const prefix = workspaceTargetPrefix(scope.rootIssue);
54	
55	  // Created before the restore attempt, and kept even when there is nothing to
56	  // restore. The agent is told this path exists; a missing directory would make
57	  // that sentence false on every first run.
58	  mkdirSync(values.dest, { recursive: true });
59	  const restored = restoreWorkspace(prefix, values.dest);
60	
61	  const githubOutput = process.env.GITHUB_OUTPUT;
62	  if (githubOutput) {
63	    appendFileSync(githubOutput, `root_issue=${scope.rootIssue}\nrestored=${restored}\n`);
64	  }
65	  console.error(
66	    restored
67	      ? `[atomaton-workspace] restored ${prefix} into ${values.dest}`
68	      : `[atomaton-workspace] nothing stored at ${prefix} yet; ${values.dest} starts empty`,
69	  );
70	}
71	
72	if (import.meta.main) main();

